def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            core, prerelease = version_part.split('-', 1)
        else:
            core = version_part
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            identifiers = prerelease.split('.')
            for identifier in identifiers:
                # Check if all-digit
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))  # 0 prefix for numeric
                else:
                    prerelease_identifiers.append((1, identifier))  # 1 prefix for string

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # For sorting: version without pre-release sorts after version with pre-release
        # So we use: (major, minor, patch, has_prerelease, prerelease_identifiers, original_index)
        # has_prerelease = 1 if no prerelease (sorts after), 0 if has prerelease (sorts before)
        has_prerelease = 1 if not prerelease_identifiers else 0

        return (major, minor, patch, has_prerelease, prerelease_identifiers, index)

    # Create list of (index, version) to maintain stable sort
    indexed_versions = list(enumerate(versions))
    # Sort by the sort key
    sorted_versions = sorted(indexed_versions, key=sort_key)
    # Extract just the version strings
    return [version for _, version in sorted_versions]

